const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const menus=[['home','◈','전체 현황'],['partners','◇','협력업체·상품'],['orders','▤','구매·발주'],['receipts','⇥','입고·검수'],['stock','▦','재고·센터 이관'],['settlement','₩','매입·정산']];
const seed=()=>({partnerApproved:false,orderStage:0,orders:[],inspection:false,transfer:0,paid:false,log:[]});let state;try{state=JSON.parse(localStorage.getItem('supply-admin-demo-v1'))||seed()}catch{state=seed()}let page='home',query='',filter='전체',partnerTab='업체';
function save(msg){state.log.unshift({text:msg,time:new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})});localStorage.setItem('supply-admin-demo-v1',JSON.stringify(state));render();toast(msg)}function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)}
function go(p){page=p;query='';filter='전체';render();window.scrollTo(0,0)}function pill(s,c=''){return `<span class="pill ${c}">${s}</span>`}function head(k,t,d,action=''){return `<div class="pagehead"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p>${d}</p></div>${action}</div>`}function panel(t,body,sub=''){return `<section class="panel"><div class="panelhead"><h2>${t}</h2><small>${sub}</small></div>${body}</section>`}function table(cols,rows){return `<div class="tablewrap"><table><thead><tr>${cols.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${cols.length}" class="empty">조건에 맞는 내역이 없습니다.</td></tr>`}</tbody></table></div>`}function metrics(items){return `<div class="metrics">${items.map(([a,b,c])=>`<div class="metric"><label>${a}</label><strong>${b}</strong><small>${c}</small></div>`).join('')}</div>`}function toolbar(statuses){return `<div class="toolbar"><input id="search" aria-label="목록 검색" placeholder="업체·상품·문서번호 검색" value="${esc(query)}"><select id="filter" aria-label="상태 필터">${statuses.map(s=>`<option ${s===filter?'selected':''}>${s}</option>`).join('')}</select></div>`}function match(text,status){return text.toLowerCase().includes(query.toLowerCase())&&(filter==='전체'||filter===status)}function modal(html){$('#modal').innerHTML=`<div class="modalhead"><span class="eyebrow">업무 상세</span><button class="close" aria-label="닫기" onclick="closeModal()">×</button></div>${html}`;$('#dialog').showModal()}function closeModal(){$('#dialog').close()}function doAction(fn,msg){closeModal();fn();save(msg)}
const orderNames=['공급 회신 대기','변경 협의','발주 확정','출하 보고'];function orderStatus(){return orderNames[state.orderStage]||'출하 보고'}
function render(){ $('#nav').innerHTML=menus.map(([p,i,t])=>`<button class="${page===p?'active':''}" onclick="go('${p}')"><b>${i}</b><span>${t}</span></button>`).join('');$('#main').innerHTML=views[page]();if($('#search'))$('#search').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};if($('#filter'))$('#filter').onchange=e=>{filter=e.target.value;render()};}
const views={home(){const dc=$('#center').value==='DC · 인천',ppc=$('#center').value==='PPC · 강남';return head('OVERVIEW','오늘의 운영 현황','공급부터 정산까지, 지금 확인할 업무를 한눈에 봅니다.',`<button class="primary" onclick="showGuide()">업무 흐름 따라보기 →</button>`)+metrics([['확인할 협력업체',state.partnerApproved?'0':'1','신규 등록·증빙 심사'],['진행 중 발주',String(2+state.orders.length),state.orderStage===1?'부분 공급 회신 · 협의 필요':'발주 응답·납품 진행'],['현물 재고',dc?'8,240':ppc?'2,360':'11,080','이동 중 포함 · 예정 물량 제외'],['검수·정산 확인',state.inspection?'1':'2','파손 판정·매입 인정 분리']])+panel('하나의 거래, 여섯 단계',`<div class="flow">${[['partners','01','협력업체·상품','등록·계약·승인'],['orders','02','구매·발주','수량·납기 합의'],['receipts','03','입고·검수','실물·품질 확인'],['stock','04','재고·이관','DC → PPC 보충'],['settlement','05','매입·정산','인정 수량·지급'],['home','06','운영 현황','지연·차이 추적']].map(([p,n,t,d])=>`<button onclick="${p==='home'?'showGuide()':`go('${p}')`}"><span>STEP ${n}</span><b>${t}</b><small>${d}</small></button>`).join('')}</div>`,'각 단계를 눌러 확인')+`<div class="grid">${panel('우선 확인할 업무',`${!state.partnerApproved?task('◇','그린푸드 · 신규 협력업체 신청','사업자·계좌·계약 상태를 확인하세요.','partners'):''}${state.orderStage<2?task('▤','한빛음료 · 공급 가능 수량 회신','발주 100개, 공급 가능 80개인 시나리오입니다.','orders'):''}${task('⇥','프레시팜 · 파손 5개 검수','출하 100개 / 실입고 100개 / 정상 95개.','receipts')}${task('₩','매입 인정 기준 확인','파손 수량은 계약 확인 후 별도로 판단합니다.','settlement')}`)}${panel('재고 구성',`<div class="stockline"><span>DC · 인천</span><b>8,240개</b></div><div class="stockline"><span>PPC · 강남</span><b>2,360개</b></div><div class="stockline"><span>센터 간 이동 중</span><b>480개</b></div><div class="stockbar"><span style="width:74%;background:#207859"></span><span style="width:21%;background:#88b597"></span><span style="width:5%;background:#dbcba5"></span></div><div class="notice">전체 현물 11,080개<br>할당·격리는 현물의 일부입니다. 별도로 더하지 않습니다.</div><button onclick="go('stock')">센터별 상세 확인 →</button>`)}</div>`+panel('시연 처리 이력',state.log.length?table(['시각','처리 내용'],state.log.slice(0,5).map(l=>[l.time,esc(l.text)])):'<p class="mini">승인·발주·검수 등의 시연을 진행하면 처리 이력이 쌓입니다.</p>')},
partners(){let rows=[['SUP-000001','한빛음료','음료','거래 가능'],['SUP-000002','프레시팜','신선식품','거래 가능'],['SUP-000003','그린푸드','가공식품',state.partnerApproved?'거래 가능':'심사 중']];return head('PARTNERS','협력업체·상품','업체 등록, 계약, 상품 제안을 각각 확인하고 승인합니다.')+`<div class="tabs">${['업체','상품 제안'].map(t=>`<button class="${partnerTab===t?'active':''}" onclick="partnerTab='${t}';render()">${t}</button>`).join('')}</div>`+`<div class="notice">공급사 포털에서 제출한 신청을 내부에서 검토합니다. 업체 등록 승인과 계약 체결, 상품 거래 승인은 별도입니다.</div>`+panel(partnerTab==='업체'?'협력업체 목록':'상품 제안 목록',toolbar(['전체','거래 가능','심사 중'])+(partnerTab==='업체'?table(['업체코드','협력업체','취급상품','계약','상태',''],rows.filter(r=>match(r.join(' '),r[3])).map(r=>[r[0],`<b>${r[1]}</b><small>공급사 포털 연결</small>`,r[2],r[3]==='심사 중'?'검토 중':'체결',pill(r[3],r[3]==='심사 중'?'amber':'green'),`<button onclick="partnerDetail('${r[1]}')">상세 보기</button>`])):table(['신청번호','상품','협력업체','구매단위','상태',''],match('그린푸드 귀리 스낵','심사 중')?[['상품 제안 003','귀리 스낵 40g','그린푸드','1박스 / 24개',pill('심사 중','amber'),`<button onclick="productDetail()">제안 검토</button>`]]:[])))},
orders(){const rows=[{id:'PO-20261012-000001',name:'한빛음료',item:'탄산수 500ml',qty:100,status:orderStatus()},{id:'PO-20261012-000002',name:'프레시팜',item:'샐러드 키트',qty:100,status:'입고·검수'},...state.orders];return head('PURCHASE','구매·발주','필요 수량을 발주하고, 공급사의 회신과 납품 실적을 연결합니다.',`<button class="primary" onclick="newOrder()">＋ 발주 초안</button>`)+metrics([['진행 발주',String(rows.length),'공급사별 PO 관리'],['회신 가능 수량',state.orderStage?'80개':'확인 중','한빛음료 · 요청 100개'],['미해결 잔량',state.orderStage===1?'20개':'—','변경·취소·이월 협의'],['납품센터','DC 인천','센터 간 이동과 공급사 발주 구분']])+panel('발주 목록',toolbar(['전체',...orderNames,'입고·검수','초안'])+table(['발주번호','협력업체·상품','요청 수량','납품센터','상태',''],rows.filter(r=>match(r.id+r.name+r.item,r.status)).map((r,i)=>[r.id,`<b>${esc(r.name)}</b><small>${esc(r.item)}</small>`,`${r.qty}개`,'DC · 인천',pill(r.status,r.status==='변경 협의'?'amber':'blue'),`<button onclick="${r.id.endsWith('000001')?'orderDetail()':r.id.endsWith('000002')?"go('receipts')":`draftDetail('${r.id}')`}">상세 보기</button>`])))+`<div class="notice">공급 가능 80개 회신만으로 원발주 100개가 자동 변경되지는 않습니다. 협의 결과를 기록한 뒤 변경·잔량 취소를 적용합니다.</div>`},
receipts(){return head('INBOUND','입고·검수','공급사의 출하 보고와 센터의 실제 입고·품질 결과를 대조합니다.')+metrics([['출하 보고','100개','프레시팜 ASN'],['센터 실입고','100개','센터 작업자 계수'],['정상 / 파손','95 / 5','수량 부족과 파손 구분'],['결과 상태',state.inspection?'확정':'검토 중','매입 인정은 계약에 따라 별도 판단']])+panel('공급사 입고',table(['입고 문서','상품·협력업체','예정 / 실입고','검수','상태',''],[['RCV-20261012-000001','샐러드 키트<small>프레시팜 · ASN-20261012-000001</small>','100 / 100개','정상 95 · 파손 5',pill(state.inspection?'결과 확정':'차이 검토',state.inspection?'green':'amber'),`<button onclick="receiptDetail()">검수 결과</button>`],...(state.orderStage===3?[['입고 예정','탄산수 500ml<small>한빛음료 · ASN-20261012-000002</small>','80 / 미도착','대기',pill('도착 대기','blue'),'<span class="mini">출하 보고는 재고 미반영</span>']]:[])]))+panel('문제 발생 시 처리',table(['상황','즉시 처리','확인 후 다음 단계'],[['출하 100 · 실입고 98','출하·실입고 수량 각각 보존','증빙 확인 · 차이 2개 조사'],['실입고 100 · 파손 5','파손 실물 구분·증빙 기록','반품·재납품·매입 인정은 계약 확인'],['검수 결과 이의 제기','원결과 보존 · 문서별 문의','재검토·정정 이력 연결']]))},
stock(){const scope=$('#center').value;const rows=[['DC · 인천','8,240','7,600','420','220'],['PPC · 강남','2,360','1,900','380','80']].filter(r=>scope==='전체 센터'||r[0]===scope);return head('INVENTORY','재고·센터 이관','센터 보유량과 이동 중 물량을 구분하고 DC에서 PPC로 보충합니다.')+panel('센터별 현물',table(['센터','현물','가용','할당','격리'],rows))+`<div class="notice">가용·할당·격리는 현물의 구성입니다. 입고 예정 1,200개는 현물에 합산하지 않습니다. 이 표는 상태를 배타적으로 나눈 시연 예시입니다.</div>`+panel('DC → PPC 보충',table(['이관번호','경로','출발 / 도착 / 잔량','상태',''],[['TRF-20261012-000001','DC 인천 → PPC 강남','12 / 10 / 2개',pill(state.transfer?'잔량 조사 중':'부분 도착','amber'),`<button onclick="transferDetail()">이관 상세</button>`]]))+panel('예약 주문과 재고',`<div class="detailgrid"><div><small>현재 현물</small><b>센터에 실제 있는 상품</b><p class="mini">즉시 출고 시 실제 가용 물량 확인</p></div><div><small>확정 입고 예정</small><b>아직 도착하지 않은 물량</b><p class="mini">예약 판매 약속에 활용 가능 · 현물과 분리</p></div></div><p class="mini">센터 간 도착은 TIN으로 기록합니다. 공급사 매입용 RCV·PUR를 중복 생성하지 않습니다.</p>`)},
settlement(){return head('FINANCE','매입·정산','발주·입고·계약을 대조해 인정 수량과 지급 내역을 확인합니다.')+metrics([['입고 확인','100개','프레시팜 · 샐러드 키트'],['매입 인정','미확정','파손 5개 계약 검토 필요'],['지급 예정','₩480,000','한빛음료 · 별도 완료 거래'],['지급 상태',state.paid?'지급 완료':'지급 대기','지급 결과 기록 시연']])+panel('정산 목록',table(['협력업체','문서·대상','인정 수량 / 금액','상태',''],[['프레시팜','RCV-20261012-000001<small>샐러드 키트 · 정상 95 / 파손 5</small>','계약 검토 필요',pill('매입 검토','amber'),`<button onclick="financeDetail()">근거 확인</button>`],['한빛음료','PUR-20261011-000001<small>전일 입고 완료 거래 · 현재 발주와 별개</small>','240개 / ₩480,000',pill(state.paid?'지급 완료':'지급 대기',state.paid?'green':'blue'),`<button onclick="paymentDetail()">지급 상세</button>`]]))+`<div class="notice amber">파손을 자동으로 매입 제외하거나 정상 입고량을 곧바로 정산 수량으로 확정하지 않습니다. 계약·검수·반품 결과를 함께 확인합니다.</div>`}};
function task(i,t,d,p){return `<div class="task"><div class="icon">${i}</div><div><b>${t}</b><p>${d}</p></div><button onclick="go('${p}')">확인 →</button></div>`}
function showGuide(){modal(`<h2>거래 흐름 따라보기</h2><p class="muted">순서대로 눌러보면 담당자와 문서가 어떻게 연결되는지 볼 수 있습니다.</p><div class="timeline"><div><b>01 · 협력업체 등록·상품 제안</b><p>그린푸드 신청 검토 · 업체·계약·상품 승인 구분</p></div><div><b>02 · 발주 100개 → 공급 가능 80개</b><p>원발주 보존 → 부족 20개 협의 → 변경·취소 확정</p></div><div><b>03 · 납품 예정·출하 보고</b><p>ASN 등록 → 센터 도착 전에는 재고 증가 없음</p></div><div><b>04 · 입고 100개 → 정상 95 / 파손 5</b><p>프레시팜 별도 거래로 검수·매입 인정의 차이 확인</p></div><div><b>05 · DC 출발 12개 → PPC 도착 10개</b><p>센터 간 이동 · 미도착 2개 유지·조사</p></div><div><b>06 · 매입 대조·정산</b><p>계약 확인 후 인정 · 지급 결과 별도 기록</p></div></div><div class="actions"><button class="primary" onclick="closeModal();go('partners')">협력업체부터 시작 →</button></div>`)}
function partnerDetail(name){const pending=name==='그린푸드'&&!state.partnerApproved;modal(`<h2>${name}</h2><p>${pill(pending?'심사 중':'거래 가능',pending?'amber':'green')} <span class="mini">가상 업체 · 제출 정보</span></p><div class="detailgrid"><div><small>사업자 증빙</small><b>제출 완료</b></div><div><small>정산 계좌</small><b>확인 완료 · 계좌번호 비노출</b></div><div><small>계약</small><b>${pending?'서명·거래조건 검토 대기':'체결 완료'}</b></div><div><small>직원 권한</small><b>상품 / 납품 / 정산 담당 구분</b></div></div><div class="notice">업체 승인 시 상품 제안은 자동 승인되지 않습니다. 공급사 계정은 자기 업체의 거래 자료만 조회합니다.</div><div class="actions"><button onclick="closeModal()">닫기</button>${pending?`<button onclick="doAction(()=>{},'그린푸드에 계약 보완 요청을 기록했습니다. 시연 데이터입니다.')">보완 요청</button><button class="primary" onclick="doAction(()=>state.partnerApproved=true,'그린푸드 증빙·계약 확인 후 거래 승인을 시연했습니다.')">증빙·계약 확인 후 승인</button>`:''}</div>`)}
function productDetail(){modal(`<h2>귀리 스낵 40g · 상품 제안</h2><div class="detailgrid"><div><small>구매단위</small><b>24개 / 박스</b></div><div><small>보관조건</small><b>상온 · 직사광선 피함</b></div><div><small>공급가·납기</small><b>협의 자료 제출</b></div><div><small>바코드·소비기한</small><b>보완 필요</b></div></div><div class="notice amber">바코드와 소비기한 정보가 확인되어야 내부 SKU 연결·거래 승인을 진행합니다.</div><div class="actions"><button class="primary" onclick="doAction(()=>{},'귀리 스낵의 바코드·소비기한 보완 요청을 기록했습니다.')">보완 요청 기록</button></div>`)}
function orderDetail(){const st=state.orderStage;modal(`<h2>한빛음료 · 탄산수 500ml</h2><p class="mini">PO-20261012-000001 · 원발주 번호 유지</p><div class="steps">${orderNames.map((s,i)=>`<span class="${i===st?'current':''}">${s}</span>`).join('')}</div><div class="detailgrid"><div><small>최초 발주 수량</small><b>100개</b></div><div><small>공급사 회신</small><b>${st?'80개 · 10월 14일 납품 가능':'아직 수신 전'}</b></div><div><small>유효 발주 수량</small><b>${st>=2?'80개 · 승인 취소 20개':'100개 · 원발주 유지'}</b></div><div><small>납품센터</small><b>DC · 인천</b></div></div><div class="notice">${st===0?'다음 버튼은 공급사 포털에서 회신이 도착하는 상황을 시연합니다.':st===1?'20개 부족 회신입니다. 이번 시연에서는 양사가 납기 변경과 잔량 20개 취소에 합의한 것으로 기록합니다.':st===2?'PCH 납기 변경·PCN 잔량 취소 이력을 보존했습니다. 확정된 80개에 대해 ASN을 등록합니다.':'ASN-20261012-000002 · 80개 출하 보고. 센터 실입고는 아직 확정되지 않았습니다.'}</div><div class="actions"><button onclick="closeModal()">닫기</button>${st<3?`<button class="primary" onclick="advanceOrder()">${['공급사 80개 회신 시연','합의된 변경·20개 취소 기록','ASN 80개·출하 보고 시연'][st]}</button>`:`<button class="primary" onclick="closeModal();go('receipts')">입고 예정 확인 →</button>`}</div>`)}
function advanceOrder(){const msgs=['공급사 80개 회신 수신 · 원발주 100개는 유지합니다.','양사 합의 기록 · 납기 변경 PCH 및 잔량 20개 취소 PCN을 반영했습니다.','ASN 80개 출하 보고 · 센터 재고는 아직 증가하지 않습니다.'];const i=state.orderStage;doAction(()=>state.orderStage=Math.min(i+1,3),msgs[i])}
function newOrder(){modal(`<h2>발주 초안 만들기</h2><p class="mini">초안 저장은 발주 전달·공급사 수락과 별도입니다.</p><form id="newform"><label class="field">협력업체<select name="supplier"><option>한빛음료</option><option>프레시팜</option></select></label><label class="field">상품<input name="item" required maxlength="60" placeholder="예: 탄산수 500ml"></label><label class="field">발주 수량 · 낱개<input name="qty" type="number" min="1" max="100000" step="1" required value="100"></label><label class="field">납품센터<input value="DC · 인천" readonly></label><div class="actions"><button type="button" onclick="closeModal()">취소</button><button class="primary">초안 저장</button></div></form>`);$('#newform').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),id='PO-20261012-'+String(state.orders.length+3).padStart(6,'0');doAction(()=>state.orders.push({id,name:f.get('supplier'),item:f.get('item'),qty:Number(f.get('qty')),status:'초안'}),`${id} · 발주 초안을 저장했습니다.`)}}
function draftDetail(id){const r=state.orders.find(o=>o.id===id);modal(`<h2>발주 초안</h2><p>${id}</p><div class="notice">${esc(r.name)} · ${esc(r.item)} · ${r.qty}개<br>공급사에 전달하기 전 초안입니다.</div><div class="actions"><button onclick="closeModal()">닫기</button></div>`)}
function receiptDetail(){modal(`<h2>입고·검수 결과 확인</h2><p class="mini">RCV-20261012-000001 · 프레시팜</p>${table(['구분','수량','담당'],[['ASN 출하 보고','100개','공급사'],['실입고 계수','100개','센터 작업자'],['정상 / 파손','95 / 5개','센터 검수']])}<div class="notice amber">파손 5개는 정상 재고와 구분합니다. 검수 결과 확정으로 매입 인정·폐기 승인이 자동 처리되지 않습니다.</div><div class="actions"><button onclick="closeModal()">닫기</button>${!state.inspection?`<button class="primary" onclick="doAction(()=>state.inspection=true,'정상 95개·파손 5개 검수 결과를 확정했습니다. 매입 인정은 별도 검토입니다.')">검수 결과 확정</button>`:`<button class="primary" onclick="closeModal();go('settlement')">매입 검토 →</button>`}</div>`)}
function transferDetail(){modal(`<h2>센터 이관 · 부분 도착</h2><p class="mini">TRF-20261012-000001 · DC 인천 → PPC 강남</p><div class="timeline"><div><b>로케이션 할당·집품</b><p>이관 대상 재고 확보 · 작업자 배정과 별도</p></div><div><b>TOUT · 12개 출발</b><p>출발센터에서 이동 중으로 추적</p></div><div><b>TIN · 10개 도착</b><p>PPC 실제 도착수량 기록 · 추가 도착은 새 TIN</p></div><div><b>미도착 2개</b><p>전체 완료·자동 폐기 금지 · 운송·상하차 근거 확인</p></div></div><div class="actions"><button onclick="closeModal()">닫기</button><button class="primary" onclick="doAction(()=>state.transfer=1,'미도착 2개 잔량 조사 요청을 기록했습니다. 수량은 유지합니다.')">잔량 조사 요청</button></div>`)}
function financeDetail(){modal(`<h2>매입 인정 근거 검토</h2>${table(['근거','현재 결과'],[['PO·ASN','100개 발주·출하'],['RCV 검수',state.inspection?'확정 · 정상 95 / 파손 5':'검토 중 · 정상 95 / 파손 5'],['계약 조건','파손 인정·재납품 조건 추가 확인'],['PUR 매입','인정 수량·금액 미확정']])}<div class="notice amber">계약을 확인하기 전 95개 또는 100개를 매입 수량으로 단정하지 않습니다. 센터 간 TIN은 신규 매입이 아닙니다.</div><div class="actions"><button class="primary" onclick="doAction(()=>{},'프레시팜 파손 5개의 매입 인정·재납품 조건 확인 요청을 기록했습니다.')">계약 조건 확인 요청</button></div>`)}
function paymentDetail(){modal(`<h2>한빛음료 · 지급 상세</h2><p class="mini">전일 완료 거래 · PUR-20261011-000001</p><div class="detailgrid"><div><small>매입 인정 수량</small><b>240개</b></div><div><small>지급 금액</small><b>₩480,000</b></div><div><small>대조 결과</small><b>발주·입고·계약 확인 완료</b></div><div><small>지급 상태</small><b>${state.paid?'지급 완료':'지급 대기'}</b></div></div><div class="notice">지급 완료 버튼은 결과 기록을 시연합니다. 실제 송금은 발생하지 않습니다.</div><div class="actions"><button onclick="closeModal()">닫기</button>${!state.paid?`<button class="primary" onclick="doAction(()=>state.paid=true,'한빛음료 전일 거래 지급 결과를 기록했습니다. 실제 송금 없는 시연입니다.')">지급 결과 기록 시연</button>`:''}</div>`)}
$('#center').onchange=()=>render();$('#help').onclick=showGuide;$('#reset').onclick=()=>modal(`<h2>시연 데이터 초기화</h2><p>이 브라우저에서 만든 초안과 시연 처리 이력을 초기 상태로 되돌립니다.</p><div class="actions"><button onclick="closeModal()">취소</button><button class="primary" onclick="closeModal();state=seed();localStorage.removeItem('supply-admin-demo-v1');render();toast('시연 데이터를 초기화했습니다.')">초기화</button></div>`);$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))closeModal()});render();
